// test/upload-compat.test.js — /api/admin/upload against the installed Multer and Express.
// One real server child process with a throwaway DATA_DIR and a test-only admin password;
// uploads are small generated byte buffers, never real photos or customer data.
const { test, before, after } = require('node:test');
const assert = require('node:assert');
const { spawn } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const net = require('node:net');

const ROOT = path.join(__dirname, '..');
const TEST_PASSWORD = 'test-only-admin-password-123';
let child, closed, base, dataDir, uploadDir, cookie;

const freePort = () => new Promise((resolve, reject) => {
  const s = net.createServer().listen(0, '127.0.0.1', () => {
    const { port } = s.address();
    s.close(() => resolve(port));
  }).on('error', reject);
});

async function stopServer() {
  if (child) {
    if (child.exitCode === null && child.signalCode === null) child.kill();
    await closed;
  }
  if (dataDir) fs.rmSync(dataDir, { recursive: true, force: true });
}

before(async () => {
  dataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'vornetic-test-'));
  uploadDir = path.join(dataDir, 'uploads');
  try {
    const port = await freePort();
    const env = { ...process.env, PORT: String(port), DATA_DIR: dataDir, NODE_ENV: 'test', ADMIN_PASSWORD: TEST_PASSWORD };
    for (const k of ['SMTP_HOST', 'SMTP_USER', 'SMTP_PASS', 'STRIPE_SECRET_KEY']) delete env[k];
    child = spawn(process.execPath, ['server.js'], { cwd: ROOT, env, stdio: ['ignore', 'pipe', 'pipe'] });
    closed = new Promise(r => child.once('close', r));
    let log = '';
    await new Promise((resolve, reject) => {
      const timer = setTimeout(() => reject(new Error('server did not start:\n' + log)), 15000);
      const onData = d => { log += d; if (log.includes('Vornetic →')) { clearTimeout(timer); resolve(); } };
      child.stdout.on('data', onData);
      child.stderr.on('data', onData);
      child.once('exit', code => { clearTimeout(timer); reject(new Error(`server exited (${code}):\n${log}`)); });
    });
    base = `http://127.0.0.1:${port}`;
    const res = await fetch(base + '/api/admin/login', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ password: TEST_PASSWORD }),
    });
    assert.strictEqual(res.status, 200);
    cookie = res.headers.get('set-cookie').split(';')[0];
  } catch (err) {
    await stopServer();
    throw err;
  }
});
after(stopServer);

const listUploads = () => fs.readdirSync(uploadDir).sort();
const bytes = (n, seed = 1) => Buffer.from(Array.from({ length: n }, (_, i) => (i * 31 + seed) & 255));
function upload(files, { auth = true, field = 'files' } = {}) {
  const form = new FormData();
  for (const [name, buf] of files) form.append(field, new Blob([buf]), name);
  return fetch(base + '/api/admin/upload', { method: 'POST', body: form, headers: auth ? { Cookie: cookie } : {} });
}

test('installed express and multer are the audited versions', () => {
  assert.strictEqual(require('express/package.json').version.split('.')[0], '4');
  assert.strictEqual(require('multer/package.json').version.split('.')[0], '2');
});

test('photos and videos upload via diskStorage and are served back unchanged', async () => {
  const before = listUploads();
  const jpg = bytes(2048, 1), png = bytes(1024, 2), mp4 = bytes(4096, 3);
  const res = await upload([['front.jpg', jpg], ['Side.PNG', png], ['clip.mp4', mp4]]);
  assert.strictEqual(res.status, 200);
  const { ok, media } = await res.json();
  assert.strictEqual(ok, true);
  assert.deepStrictEqual(media.map(m => m.type), ['image', 'image', 'video']);
  for (const m of media) assert.match(m.src, /^\/uploads\/[0-9a-f]{16}\.(jpg|png|mp4)$/);   // random name, lower-case ext
  assert.strictEqual(listUploads().length, before.length + 3);

  const served = Buffer.from(await (await fetch(base + media[0].src)).arrayBuffer());
  assert.ok(served.equals(jpg), 'served file differs from upload');
});

test('fileFilter rejects other file types with 400 and stores nothing', async () => {
  const before = listUploads();
  for (const name of ['evil.html', 'run.exe', 'noext', 'photo.jpg.svg']) {
    const res = await upload([[name, bytes(64)]]);
    assert.strictEqual(res.status, 400, name);
    assert.match((await res.json()).error, /JPG, PNG, WEBP/);
  }
  assert.deepStrictEqual(listUploads(), before);
});

test('a path in the client file name cannot escape the uploads folder', async () => {
  const res = await upload([['../../../escape.jpg', bytes(64)]]);
  assert.strictEqual(res.status, 200);
  const [m] = (await res.json()).media;
  assert.match(m.src, /^\/uploads\/[0-9a-f]{16}\.jpg$/);
  assert.strictEqual(fs.existsSync(path.join(dataDir, '..', 'escape.jpg')), false);
  assert.strictEqual(fs.existsSync(path.join(ROOT, 'escape.jpg')), false);
});

test('photos over 12 MB are discarded after upload', async () => {
  const before = listUploads();
  const res = await upload([['big.jpg', Buffer.alloc(12 * 1024 * 1024 + 1)], ['small.webp', bytes(100)]]);
  assert.strictEqual(res.status, 200);
  const { media } = await res.json();
  assert.strictEqual(media.length, 1);
  assert.match(media[0].src, /\.webp$/);
  assert.strictEqual(listUploads().length, before.length + 1);
});

test('more than 20 files is rejected with 400 and partial files are cleaned up', async () => {
  const before = listUploads();
  const files = Array.from({ length: 21 }, (_, i) => [`p${i}.jpg`, bytes(16, i)]);
  const res = await upload(files);
  assert.strictEqual(res.status, 400);
  assert.ok((await res.json()).error);
  assert.deepStrictEqual(listUploads(), before);
});

test('unexpected form field is rejected with 400', async () => {
  const before = listUploads();
  const res = await upload([['a.jpg', bytes(16)]], { field: 'other' });
  assert.strictEqual(res.status, 400);
  assert.deepStrictEqual(listUploads(), before);
});

test('upload without an admin session is refused and stores nothing', async () => {
  const before = listUploads();
  const res = await upload([['x.jpg', bytes(64)]], { auth: false });
  assert.strictEqual(res.status, 401);
  assert.deepStrictEqual(listUploads(), before);
});
